-- Seed global public talk themes (source: prisma/data/discursos_publicos.json)
ON CONFLICT ("number") DO UPDATE SET
  "title" = EXCLUDED."title",
  "fullTitle" = EXCLUDED."fullTitle",
  "sanitizedFullTitle" = EXCLUDED."sanitizedFullTitle",
  "documentId" = EXCLUDED."documentId",
  "path" = EXCLUDED."path",
  "deletedAt" = NULL,
  "updatedAt" = CURRENT_TIMESTAMP;
